#include <string.h>
#include "log.h"
#include "pal_time.h"

typedef struct PAPACC_TEST_SINK { PAPACC_SIZE call_count; void *received_context; PAPACC_LOG_RECORD record; char retained_message[64]; } PAPACC_TEST_SINK;
static void sink_callback(void *context,const PAPACC_LOG_RECORD *record){PAPACC_TEST_SINK*s=(PAPACC_TEST_SINK*)context;PAPACC_SIZE n=(PAPACC_SIZE)strlen(record->message);if(n>=sizeof(s->retained_message))n=sizeof(s->retained_message)-1U;++s->call_count;s->received_context=context;s->record=*record;(void)memcpy(s->retained_message,record->message,n);s->retained_message[n]='\0';}
static void emit_all(PAPACC_LOGGER*l){papacc_log_event(l,PAPACC_LOG_ERROR,PAPACC_LOG_EVENT_PROTOCOL_REJECTED,PAPACC_LOG_CATEGORY_PROTOCOL,PAPACC_LOG_COMPONENT_SERVER_IO_LOOP,PAPACC_LOG_OPERATION_ESTABLISH,PAPACC_TRUE,PAPACC_RESULT_PROTOCOL_ERROR,NULL,"error");papacc_log_event(l,PAPACC_LOG_WARNING,PAPACC_LOG_EVENT_CONNECTION_REJECTED,PAPACC_LOG_CATEGORY_NETWORK,PAPACC_LOG_COMPONENT_SERVER_IO_LOOP,PAPACC_LOG_OPERATION_ACCEPT,PAPACC_TRUE,PAPACC_RESULT_LIMIT_EXCEEDED,NULL,"warning");papacc_log_event(l,PAPACC_LOG_INFO,PAPACC_LOG_EVENT_CONNECTION_ACCEPTED,PAPACC_LOG_CATEGORY_NETWORK,PAPACC_LOG_COMPONENT_SERVER_IO_LOOP,PAPACC_LOG_OPERATION_ACCEPT,PAPACC_TRUE,PAPACC_RESULT_OK,NULL,"info");papacc_log_event(l,PAPACC_LOG_DEBUG,PAPACC_LOG_EVENT_SESSION_CLEANUP,PAPACC_LOG_CATEGORY_SESSION,PAPACC_LOG_COMPONENT_SERVER_IO_LOOP,PAPACC_LOG_OPERATION_CLEANUP,PAPACC_TRUE,PAPACC_RESULT_OK,NULL,"debug");papacc_log_event(l,PAPACC_LOG_TRACE,PAPACC_LOG_EVENT_DATA_TICKETS_EXPIRED,PAPACC_LOG_CATEGORY_SESSION,PAPACC_LOG_COMPONENT_SERVER_IO_LOOP,PAPACC_LOG_OPERATION_EXPIRE,PAPACC_TRUE,PAPACC_RESULT_OK,NULL,"trace");}
int main(void){PAPACC_TEST_SINK s={0};PAPACC_LOGGER l;PAPACC_LOG_CONTEXT c=PAPACC_LOG_CONTEXT_INITIALIZER;PAPACC_U64 before,after;PAPACC_LOG_LEVEL levels[6]={PAPACC_LOG_LEVEL_OFF,PAPACC_LOG_ERROR,PAPACC_LOG_WARNING,PAPACC_LOG_INFO,PAPACC_LOG_DEBUG,PAPACC_LOG_TRACE};PAPACC_SIZE expected[6]={0,1,2,3,4,5},i;if(papacc_logger_init(&l,sink_callback,&s,PAPACC_LOG_TRACE)!=PAPACC_RESULT_OK)return 1;c.fields=PAPACC_LOG_CONTEXT_CONNECTION_ID|PAPACC_LOG_CONTEXT_SESSION_ID|PAPACC_LOG_CONTEXT_CHANNEL_ID|PAPACC_LOG_CONTEXT_LOCAL_ENDPOINT|PAPACC_LOG_CONTEXT_REMOTE_ENDPOINT;c.connection_instance_id=11;c.session_instance_id=12;c.channel_instance_id=13;(void)memcpy(c.local_endpoint,"127.0.0.1:39999",16);(void)memcpy(c.remote_endpoint,"127.0.0.1:50000",16);if(papacc_pal_monotonic_time_ns(&before)!=PAPACC_RESULT_OK)return 2;papacc_log_event(&l,PAPACC_LOG_WARNING,PAPACC_LOG_EVENT_CONNECTION_REJECTED,PAPACC_LOG_CATEGORY_NETWORK,PAPACC_LOG_COMPONENT_SERVER_IO_LOOP,PAPACC_LOG_OPERATION_ACCEPT,PAPACC_TRUE,PAPACC_RESULT_LIMIT_EXCEEDED,&c,"delivery");if(papacc_pal_monotonic_time_ns(&after)!=PAPACC_RESULT_OK)return 3;if(s.call_count!=1||s.received_context!=&s)return 4;if(s.record.level!=PAPACC_LOG_WARNING||s.record.event_id!=PAPACC_LOG_EVENT_CONNECTION_REJECTED||s.record.category!=PAPACC_LOG_CATEGORY_NETWORK||s.record.component_id!=PAPACC_LOG_COMPONENT_SERVER_IO_LOOP||s.record.operation!=PAPACC_LOG_OPERATION_ACCEPT||s.record.result_valid!=PAPACC_TRUE||s.record.result!=PAPACC_RESULT_LIMIT_EXCEEDED)return 5;if(s.record.context.fields!=c.fields||s.record.context.connection_instance_id!=11||strcmp(s.record.context.local_endpoint,"127.0.0.1:39999")!=0||strcmp(s.record.context.remote_endpoint,"127.0.0.1:50000")!=0)return 6;if(strcmp(s.retained_message,"delivery")!=0||s.record.monotonic_timestamp_valid!=PAPACC_TRUE||s.record.monotonic_timestamp_ns<before||s.record.monotonic_timestamp_ns>after)return 7;papacc_log_event(&l,PAPACC_LOG_WARNING,PAPACC_LOG_EVENT_CONNECTION_REJECTED,PAPACC_LOG_CATEGORY_NETWORK,PAPACC_LOG_COMPONENT_SERVER_IO_LOOP,PAPACC_LOG_OPERATION_ACCEPT,PAPACC_TRUE,PAPACC_RESULT_LIMIT_EXCEEDED,NULL,"different wording");if(s.record.event_id!=PAPACC_LOG_EVENT_CONNECTION_REJECTED||strcmp(s.retained_message,"different wording")!=0)return 8;for(i=0;i<6;++i){s.call_count=0;if(papacc_logger_init(&l,sink_callback,&s,levels[i])!=PAPACC_RESULT_OK)return 9;emit_all(&l);if(s.call_count!=expected[i])return 10;}if(papacc_logger_init(NULL,sink_callback,&s,PAPACC_LOG_INFO)!=PAPACC_RESULT_INVALID_ARGUMENT||papacc_logger_init(&l,NULL,&s,PAPACC_LOG_INFO)!=PAPACC_RESULT_INVALID_ARGUMENT||papacc_logger_init(&l,sink_callback,&s,(PAPACC_LOG_LEVEL)99)!=PAPACC_RESULT_INVALID_ARGUMENT)return 11;s.call_count=0;papacc_log_event(NULL,PAPACC_LOG_INFO,PAPACC_LOG_EVENT_RUNTIME_STARTED,PAPACC_LOG_CATEGORY_RUNTIME,PAPACC_LOG_COMPONENT_RUNTIME,PAPACC_LOG_OPERATION_STARTUP,PAPACC_TRUE,PAPACC_RESULT_OK,NULL,"x");papacc_log_event(&l,(PAPACC_LOG_LEVEL)99,PAPACC_LOG_EVENT_RUNTIME_STARTED,PAPACC_LOG_CATEGORY_RUNTIME,PAPACC_LOG_COMPONENT_RUNTIME,PAPACC_LOG_OPERATION_STARTUP,PAPACC_TRUE,PAPACC_RESULT_OK,NULL,"x");papacc_log_event(&l,PAPACC_LOG_INFO,PAPACC_LOG_EVENT_RUNTIME_STARTED,PAPACC_LOG_CATEGORY_RUNTIME,PAPACC_LOG_COMPONENT_RUNTIME,PAPACC_LOG_OPERATION_STARTUP,PAPACC_TRUE,PAPACC_RESULT_OK,NULL,NULL);if(s.call_count!=0)return 12;return 0;}
